import random


def test_parse_plain_amount():
    assert parse_amount("12.34") == 1234
    assert parse_amount("7") == 700


def test_parse_single_decimal_digit_means_tens_of_cents():
    assert parse_amount("1.5") == 150
    assert parse_amount("0.5") == 50


def test_parse_dollar_sign_and_thousands_separators():
    assert parse_amount("$1,234,567.08") == 123456708
    assert parse_amount("1234567") == 123456700


def test_parse_negative_amount_of_at_least_one_dollar():
    assert parse_amount("-12.50") == -1250
    assert parse_amount("-$1,000") == -100000


def test_parse_refund_under_one_dollar_keeps_its_sign():
    assert parse_amount("-0.05") == -5
    assert parse_amount("-$0.99") == -99
    assert parse_amount("-0.4") == -40


def test_parse_ignores_surrounding_whitespace_on_refunds():
    assert parse_amount("  -0.40\n") == -40
    assert parse_amount("\t-$3.10 ") == -310


def test_parse_rejects_malformed_amounts():
    for bad in ["12,34", "1.234", "", "--1", "$-1", "1.", ".5", "abc", "1,2345", "- 1"]:
        try:
            parse_amount(bad)
        except ValueError:
            pass
        else:
            assert False, f"expected ValueError for {bad!r}"


def test_format_then_parse_round_trips_for_all_small_amounts():
    bad = [x for x in range(-250, 251) if parse_amount(format_amount(x)) != x]
    assert bad == []


def test_allocate_even_split_gives_extra_cent_to_first_parts():
    assert allocate(100, [1, 1, 1]) == [34, 33, 33]
    assert allocate(5, [1, 1, 1, 1]) == [2, 1, 1, 1]


def test_allocate_proportional_weights():
    assert allocate(1000, [1, 2, 3, 4]) == [100, 200, 300, 400]
    assert allocate(100, [1, 2]) == [33, 67]


def test_allocate_zero_weight_part_gets_nothing():
    assert allocate(10, [0, 1, 1]) == [0, 5, 5]
    assert allocate(-7, [3, 0, 4]) == [-3, 0, -4]


def test_allocate_refund_split_three_ways_mirrors_the_charge():
    assert allocate(-100, [1, 1, 1]) == [-34, -33, -33]


def test_allocate_refund_with_uneven_weights():
    assert allocate(-100, [1, 2]) == [-33, -67]
    assert allocate(-101, [1, 2]) == [-34, -67]


def test_allocate_refund_is_exact_negation_of_charge_randomized():
    rng = random.Random(4242)
    mismatches = []
    for _ in range(300):
        weights = [rng.randint(0, 5) for _ in range(rng.randint(1, 6))]
        if sum(weights) == 0:
            weights[0] = 1
        t = rng.randint(0, 2000)
        pos = allocate(t, weights)
        neg = allocate(-t, weights)
        if sum(pos) != t or neg != [-p for p in pos]:
            mismatches.append((t, weights, pos, neg))
    assert mismatches[:3] == []


def test_allocate_rejects_invalid_weights():
    for bad in [[], [0, 0], [1, -1]]:
        try:
            allocate(100, bad)
        except ValueError:
            pass
        else:
            assert False, f"expected ValueError for weights {bad!r}"

import random


def _rec(ts, rid):
    return {"ts": ts, "id": rid}


def _walk(records, limit):
    out, pages, cursor = [], 0, None
    while True:
        page, cursor = paginate(records, limit, cursor)
        pages += 1
        out.extend((r["ts"], r["id"]) for r in page)
        if cursor is None or pages > 1000:
            return out, pages


def test_first_page_without_cursor():
    recs = [_rec(3, 30), _rec(1, 10), _rec(2, 20)]
    page, cur = paginate(recs, 2)
    assert page == [_rec(1, 10), _rec(2, 20)]
    assert decode_cursor(cur) == (2, 20)


def test_single_page_has_no_next_cursor():
    page, cur = paginate([_rec(1, 1), _rec(2, 2)], 5)
    assert page == [_rec(1, 1), _rec(2, 2)]
    assert cur is None


def test_exactly_full_last_page_has_no_next_cursor():
    recs = [_rec(t, t) for t in range(1, 5)]
    page, cur = paginate(recs, 2)
    page2, cur2 = paginate(recs, 2, cur)
    assert page2 == [_rec(3, 3), _rec(4, 4)]
    assert cur2 is None


def test_sequential_ids_walk_whole_feed():
    recs = [_rec(t, t) for t in range(1, 8)]
    out, pages = _walk(recs, 3)
    assert out == [(t, t) for t in range(1, 8)]
    assert pages == 3


def test_later_record_with_smaller_id_is_not_skipped():
    recs = [_rec(1, 50), _rec(2, 7), _rec(3, 60)]
    page, cur = paginate(recs, 1)
    page2, _ = paginate(recs, 1, cur)
    assert page2 == [_rec(2, 7)]


def test_same_timestamp_ties_ordered_by_id_across_pages():
    recs = [_rec(5, 3), _rec(5, 1), _rec(5, 2), _rec(4, 9)]
    out, _ = _walk(recs, 2)
    assert out == [(4, 9), (5, 1), (5, 2), (5, 3)]


def test_cursor_of_deleted_record_still_positions_correctly():
    recs = [_rec(1, 1), _rec(2, 5), _rec(2, 8), _rec(3, 2)]
    cur = encode_cursor(_rec(2, 6))  # that record no longer exists
    page, nxt = paginate(recs, 10, cur)
    assert page == [_rec(2, 8), _rec(3, 2)]
    assert nxt is None


def test_randomized_walk_visits_every_record_exactly_once():
    rng = random.Random(7)
    for trial in range(40):
        ids = rng.sample(range(1, 500), rng.randint(1, 25))
        recs = [_rec(rng.randint(1, 6), i) for i in ids]
        limit = rng.randint(1, 4)
        out, pages = _walk(recs, limit)
        expected = sorted((r["ts"], r["id"]) for r in recs)
        assert (trial, out) == (trial, expected)
        assert (trial, pages) == (trial, -(-len(recs) // limit))


def test_input_list_is_not_modified():
    recs = [_rec(3, 1), _rec(1, 2), _rec(2, 3)]
    snapshot = [dict(r) for r in recs]
    paginate(recs, 2)
    assert recs == snapshot


def test_empty_feed():
    assert paginate([], 3) == ([], None)


def test_invalid_limit_raises_value_error():
    for bad in [0, -1, 2.0]:
        try:
            paginate([_rec(1, 1)], bad)
        except ValueError:
            pass
        else:
            assert False, f"expected ValueError for limit {bad!r}"


def test_invalid_cursor_raises_value_error():
    import base64
    bogus = base64.urlsafe_b64encode(b"[1, 2, 3]").decode()
    for bad in ["not-a-cursor!!", bogus]:
        try:
            paginate([_rec(1, 1)], 2, bad)
        except ValueError:
            pass
        else:
            assert False, f"expected ValueError for cursor {bad!r}"


def test_iter_feed_yields_non_empty_pages_only():
    recs = [_rec(t % 3, 100 - t) for t in range(9)]
    pages = list(iter_feed(recs, 3))
    assert [len(p) for p in pages] == [3, 3, 3]

import functools
import random


def test_compare_numeric_parts_not_lexically():
    assert compare("1.2.3", "1.10.0") == -1
    assert compare("2.0.0", "1.99.99") == 1
    assert compare("1.2.3", "1.2.3") == 0


def test_prerelease_is_lower_than_release():
    assert compare("1.0.0-alpha", "1.0.0") == -1
    assert compare("1.0.0", "1.0.0-rc.1") == 1


def test_numeric_prerelease_identifiers_compare_numerically():
    assert compare("1.0.0-rc.10", "1.0.0-rc.9") == 1
    assert compare("1.0.0-2", "1.0.0-10") == -1


def test_numeric_identifier_sorts_before_alphanumeric():
    assert compare("1.0.0-1", "1.0.0-a") == -1
    assert compare("1.0.0-alpha.beta", "1.0.0-alpha.1") == 1
    assert compare("1.0.0-9", "1.0.0-10a") == -1


def test_full_semver_spec_ordering():
    expected = ["1.0.0-alpha", "1.0.0-alpha.1", "1.0.0-alpha.beta", "1.0.0-beta",
                "1.0.0-beta.2", "1.0.0-beta.11", "1.0.0-rc.1", "1.0.0", "1.0.1", "1.1.0"]
    shuffled = expected[:]
    random.Random(3).shuffle(shuffled)
    assert sorted(shuffled, key=functools.cmp_to_key(compare)) == expected


def test_parse_version_rejects_malformed():
    for bad in ["1.2", "01.2.3", "1.2.3-", "v1.2.3", "1.2.3-a..b", "1.2.3+build"]:
        try:
            parse_version(bad)
        except ValueError:
            pass
        else:
            assert False, f"expected ValueError for {bad!r}"


def test_caret_with_nonzero_major():
    got = [satisfies(v, "^1.2.3") for v in ["1.2.3", "1.9.9", "2.0.0", "1.2.2"]]
    assert got == [True, True, False, False]


def test_caret_with_zero_major_locks_minor():
    got = [satisfies(v, "^0.2.3") for v in ["0.2.3", "0.2.9", "0.3.0", "0.9.1"]]
    assert got == [True, True, False, False]


def test_caret_with_zero_major_and_minor_locks_patch():
    got = [satisfies(v, "^0.0.3") for v in ["0.0.3", "0.0.4", "0.1.0"]]
    assert got == [True, False, False]


def test_tilde_locks_minor():
    got = [satisfies(v, "~1.2.3") for v in ["1.2.3", "1.2.9", "1.3.0", "1.2.2"]]
    assert got == [True, True, False, False]


def test_and_or_combinations():
    rng = ">=1.2.0 <1.4.0 || >=1.5.0 <1.6.0"
    got = [satisfies(v, rng) for v in ["1.3.9", "1.4.5", "1.5.0", "1.6.0"]]
    assert got == [True, False, True, False]


def test_exact_and_bare_comparators():
    assert [satisfies("1.2.3", "=1.2.3"), satisfies("1.2.3", "1.2.3"), satisfies("1.2.4", "1.2.3")] == [True, True, False]


def test_prerelease_bounds_use_precedence():
    assert satisfies("1.0.0-rc.10", ">1.0.0-rc.9") == True
    assert satisfies("1.0.0-beta.11", "^1.0.0-beta.2") == True
    assert satisfies("1.0.0-beta.3", "<=1.0.0-beta.20") == True


def test_invalid_ranges_raise_value_error():
    for bad in ["", "   ", ">=1.2.3 ||", "^1.2", ">>1.2.3", "1.2.3 || || 2.0.0"]:
        try:
            satisfies("1.2.3", bad)
        except ValueError:
            pass
        else:
            assert False, f"expected ValueError for range {bad!r}"

