import random
from datetime import date, datetime, timedelta

# 2024-03-04 is a Monday.
MON, TUE, WED, THU, FRI, SAT, SUN = (date(2024, 3, 4) + timedelta(days=i) for i in range(7))
NEXT_MON, NEXT_TUE = date(2024, 3, 11), date(2024, 3, 12)


def at(d, h, m=0, s=0):
    return datetime(d.year, d.month, d.day, h, m, s)


def _ref(start, minutes, holidays):
    def nxt(t):
        while True:
            if t.weekday() < 5 and t.date() not in holidays and 9 <= t.hour < 17:
                return t
            if t.weekday() < 5 and t.date() not in holidays and t.hour < 9:
                t = t.replace(hour=9, minute=0)
            else:
                t = (t + timedelta(days=1)).replace(hour=9, minute=0)
    t = nxt(start)
    for _ in range(minutes):
        t = nxt(t) + timedelta(minutes=1)
    return t


def test_within_one_business_day():
    assert add_business_minutes(at(MON, 10), 90) == at(MON, 11, 30)


def test_start_before_opening_counts_from_nine():
    assert add_business_minutes(at(MON, 7, 15), 30) == at(MON, 9, 30)


def test_start_after_closing_counts_from_next_morning():
    assert add_business_minutes(at(MON, 18), 60) == at(TUE, 10)


def test_spills_over_into_next_day():
    assert add_business_minutes(at(MON, 16), 120) == at(TUE, 10)


def test_deadline_exactly_at_closing_time_same_day():
    assert add_business_minutes(at(MON, 9), 480) == at(MON, 17)


def test_deadline_exactly_at_closing_time_after_spilling():
    assert add_business_minutes(at(MON, 13), 720) == at(TUE, 17)


def test_two_full_weeks_end_friday_evening():
    assert add_business_minutes(at(MON, 9), 480 * 10) == at(date(2024, 3, 15), 17)


def test_friday_afternoon_rolls_over_weekend():
    assert add_business_minutes(at(FRI, 16, 30), 60) == at(NEXT_MON, 9, 30)


def test_monday_holiday_after_weekend_is_skipped():
    assert add_business_minutes(at(FRI, 16), 120, {NEXT_MON}) == at(NEXT_TUE, 10)


def test_friday_holiday_before_weekend_is_skipped():
    assert add_business_minutes(at(THU, 16), 120, {FRI}) == at(NEXT_MON, 10)


def test_start_on_a_holiday():
    assert add_business_minutes(at(WED, 10), 60, {WED}) == at(THU, 10)


def test_zero_minutes_returns_next_business_moment():
    assert add_business_minutes(at(MON, 12, 5, 7), 0) == at(MON, 12, 5, 7)
    assert add_business_minutes(at(SAT, 12), 0) == at(NEXT_MON, 9)
    assert add_business_minutes(at(MON, 17), 0) == at(TUE, 9)


def test_next_business_moment_friday_close_with_monday_holiday():
    assert next_business_moment(at(FRI, 17), {NEXT_MON}) == at(NEXT_TUE, 9)


def test_seconds_are_carried_exactly_across_days():
    assert add_business_minutes(at(MON, 10, 0, 30), 420) == at(TUE, 9, 0, 30)


def test_negative_minutes_raise_value_error():
    try:
        add_business_minutes(at(MON, 10), -1)
    except ValueError:
        pass
    else:
        assert False, "expected ValueError"


def test_randomized_against_minute_by_minute_reference():
    rng = random.Random(99)
    base = date(2024, 3, 1)
    for trial in range(60):
        holidays = {base + timedelta(days=rng.randint(0, 20)) for _ in range(rng.randint(0, 4))}
        start = datetime.combine(base + timedelta(days=rng.randint(0, 10)), datetime.min.time()) + \
            timedelta(minutes=rng.randint(0, 24 * 60 - 1))
        minutes = rng.choice([rng.randint(0, 1500), 480 * rng.randint(1, 3), 60 * rng.randint(1, 16)])
        got = add_business_minutes(start, minutes, holidays)
        assert (trial, got) == (trial, _ref(start, minutes, holidays))

import copy


def test_scalar_override_replaces_value():
    assert deep_merge({"a": 1, "b": 2}, {"b": 3}) == {"a": 1, "b": 3}


