class TransactionalStore:
    """Key-value store with nested transactions and snapshots."""

    _TOMBSTONE = object()

    def __init__(self):
        self._committed = {}
        self._layers = []
        self._snapshots = {}

    def _lookup(self, key):
        for layer in reversed(self._layers):
            if key in layer:
                return layer[key]
        if key in self._committed:
            return self._committed[key]
        return self._TOMBSTONE

    def _visible(self):
        state = dict(self._committed)
        for layer in self._layers:
            for k, v in layer.items():
                if v is self._TOMBSTONE:
                    state.pop(k, None)
                else:
                    state[k] = v
        return state

    def get(self, key, default=None):
        value = self._lookup(key)
        return default if value is self._TOMBSTONE else value

    def set(self, key, value):
        if self._layers:
            self._layers[-1][key] = value
        else:
            self._committed[key] = value

    def delete(self, key):
        if self._lookup(key) is self._TOMBSTONE:
            raise KeyError(key)
        if self._layers:
            self._layers[-1][key] = self._TOMBSTONE
        else:
            del self._committed[key]

    def count(self, value):
        return sum(1 for v in self._visible().values() if v == value)

    def keys(self, prefix=""):
        return sorted(k for k in self._visible() if k.startswith(prefix))

    def begin(self):
        self._layers.append({})

    def commit(self):
        if not self._layers:
            raise RuntimeError("no open transaction")
        layer = self._layers.pop()
        if self._layers:
            self._layers[-1].update(layer)
        else:
            for k, v in layer.items():
                if v is self._TOMBSTONE:
                    self._committed.pop(k, None)
                else:
                    self._committed[k] = v

    def rollback(self):
        if not self._layers:
            raise RuntimeError("no open transaction")
        self._layers.pop()

    def depth(self):
        return len(self._layers)

    def snapshot(self):
        if self._layers:
            raise RuntimeError("cannot snapshot inside a transaction")
        snapshot_id = len(self._snapshots) + 1
        self._snapshots[snapshot_id] = dict(self._committed)
        return snapshot_id

    def restore(self, snapshot_id):
        if self._layers:
            raise RuntimeError("cannot restore inside a transaction")
        if snapshot_id not in self._snapshots:
            raise KeyError(snapshot_id)
        self._committed = dict(self._snapshots[snapshot_id])

