class TextBuffer:
    """Editable text with a cursor, grouped undo/redo, and bounded history."""

    def __init__(self, text="", history_limit=100):
        if history_limit < 1:
            raise ValueError("history_limit must be >= 1")
        self._text = text
        self._cursor = len(text)
        self._limit = history_limit
        self._undo = []    # [kind, start, text]
        self._redo = []
        self._mergeable = False

    @property
    def text(self):
        return self._text

    @property
    def cursor(self):
        return self._cursor

    def _record(self, kind, start, s):
        self._redo.clear()
        top = self._undo[-1] if (self._undo and self._mergeable) else None
        merged = False
        if top is not None and top[0] == kind:
            if kind == "insert":
                if start == top[1] + len(top[2]) and "\n" not in s and "\n" not in top[2]:
                    top[2] += s
                    merged = True
            elif len(s) == 1:
                if start + 1 == top[1]:
                    top[1] = start
                    top[2] = s + top[2]
                    merged = True
                elif start == top[1]:
                    top[2] += s
                    merged = True
        if not merged:
            self._undo.append([kind, start, s])
            if len(self._undo) > self._limit:
                del self._undo[0]
        self._mergeable = True

    def insert(self, pos, s):
        if not 0 <= pos <= len(self._text):
            raise IndexError("insert position out of range")
        if not s:
            return
        self._text = self._text[:pos] + s + self._text[pos:]
        self._cursor = pos + len(s)
        self._record("insert", pos, s)

    def delete(self, pos, length):
        if pos < 0 or length < 0 or pos + length > len(self._text):
            raise IndexError("delete range out of range")
        if length == 0:
            return ""
        removed = self._text[pos:pos + length]
        self._text = self._text[:pos] + self._text[pos + length:]
        self._cursor = pos
        self._record("delete", pos, removed)
        return removed

    def _apply(self, kind, start, s, forward):
        if (kind == "insert") == forward:
            self._text = self._text[:start] + s + self._text[start:]
        else:
            self._text = self._text[:start] + self._text[start + len(s):]

    def undo(self):
        if not self._undo:
            return False
