import re

_NUM = r"(?:0|[1-9][0-9]*)"
_IDENT = r"[0-9A-Za-z-]+"
_PRE = _IDENT + r"(?:\." + _IDENT + r")*"
_VERSION_RE = re.compile(r"(%s)\.(%s)\.(%s)(?:-(%s))?\Z" % (_NUM, _NUM, _NUM, _PRE))
_PART = r"(?:0|[1-9][0-9]*|[xX*])"
_PARTIAL_RE = re.compile(r"(%s)(?:\.(%s)(?:\.(%s)(?:-(%s))?)?)?\Z" % (_PART, _PART, _PART, _PRE))
_OPS = ("<=", ">=", "<", ">", "=", "~", "^")


def _parse_pre(text):
    if text is None:
        return ()
    out = []
    for ident in text.split("."):
        if ident.isdigit():
            if len(ident) > 1 and ident[0] == "0":
                raise ValueError("leading zero in prerelease")
            out.append(int(ident))
        else:
            out.append(ident)
    return tuple(out)


def _parse_version(text):
    m = _VERSION_RE.match(text)
    if not m:
        raise ValueError("invalid version %r" % (text,))
    return (int(m.group(1)), int(m.group(2)), int(m.group(3)), _parse_pre(m.group(4)))


def _pre_key(pre):
    if not pre:
        return (1,)
    return (0, tuple((0, i, "") if isinstance(i, int) else (1, 0, i) for i in pre))


def _key(v):
    return (v[0], v[1], v[2], _pre_key(v[3]))


def _parse_partial(text):
    m = _PARTIAL_RE.match(text)
    if not m:
        raise ValueError("invalid partial %r" % (text,))
    parts = [m.group(1), m.group(2), m.group(3)]
    nums = []
    wild = False
    for p in parts:
        if p is None or p in ("x", "X", "*"):
            wild = True
            nums.append(None)
        else:
            if wild:
                raise ValueError("number after wildcard")
            nums.append(int(p))
    pre = m.group(4)
    if pre is not None and None in nums:
        raise ValueError("prerelease on partial")
    return nums, _parse_pre(pre)


def _present(nums):
    return [n for n in nums if n is not None]


def _bump(present):
    # increment last element of the list, return a full version tuple
    p = list(present)
    p[-1] += 1
    while len(p) < 3:
        p.append(0)
    return (p[0], p[1], p[2], ())


def _fill(nums, pre=()):
    p = [n if n is not None else 0 for n in nums]
    return (p[0], p[1], p[2], pre)


_ALL = [(">=", (0, 0, 0, ()))]
_NONE = [("none", None)]


def _desugar(op, nums, pre):
    present = _present(nums)
    full = len(present) == 3
    if op == "~":
        if not present:
            return _ALL
        low = _fill(nums, pre)
        up = _bump(present[:2]) if len(present) >= 2 else _bump(present[:1])
        return [(">=", low), ("<", up)]
    if op == "^":
        if not present:
            return _ALL
        low = _fill(nums, pre)
        idx = len(present) - 1
        for i, n in enumerate(present):
            if n != 0:
                idx = i
                break
        return [(">=", low), ("<", _bump(present[: idx + 1]))]
    if full:
        return [(op, _fill(nums, pre))]
    if not present:
        return _NONE if op in ("<", ">") else _ALL
    if op == "=":
        return [(">=", _fill(nums)), ("<", _bump(present))]
    if op == ">":
        return [(">=", _bump(present))]
    if op == ">=":
        return [(">=", _fill(nums))]
    if op == "<":
        return [("<", _fill(nums))]
    if op == "<=":
        return [("<", _bump(present))]
    raise ValueError("bad operator")


def _parse_set(text):
    tokens = text.split()
    if not tokens:
        raise ValueError("empty comparator set")
    if "-" in tokens:
        if len(tokens) != 3 or tokens[1] != "-":
            raise ValueError("bad hyphen range")
        a_nums, a_pre = _parse_partial(tokens[0])
        b_nums, b_pre = _parse_partial(tokens[2])
        comps = [(">=", _fill(a_nums, a_pre))]
        b_present = _present(b_nums)
        if len(b_present) == 3:
            comps.append(("<=", _fill(b_nums, b_pre)))
        elif b_present:
            comps.append(("<", _bump(b_present)))
        return comps
    comps = []
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        op = "="
        for cand in _OPS:
            if tok.startswith(cand):
                op = cand
                tok = tok[len(cand):]
                break
        if tok == "":
            i += 1
            if i >= len(tokens):
                raise ValueError("operator without version")
            tok = tokens[i]
        nums, pre = _parse_partial(tok)
        comps.extend(_desugar(op, nums, pre))
        i += 1
    return comps


def _test(op, bound, v):
    if op == "none":
        return False
    a, b = _key(v), _key(bound)
    if op == "=":
        return a == b
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    raise ValueError(op)


def _set_ok(comps, v):
    if not all(_test(op, b, v) for op, b in comps):
        return False
    if v[3]:
        return any(b is not None and b[3] and b[:3] == v[:3] for op, b in comps)
    return True


def satisfies(version, range_expr):
    v = _parse_version(version)
    if range_expr.strip() == "":
        range_expr = "*"
    sets = [_parse_set(part) for part in range_expr.split("||")]
    return any(_set_ok(s, v) for s in sets)

