                raise ValueError("operator without version")
            tok = tokens[i]
        nums, pre = _parse_partial(tok)
        comps.extend(_desugar(op, nums, pre))
        i += 1
    return comps


def _test(op, bound, v):
    if op == "none":
        return False
    a, b = _key(v), _key(bound)
    if op == "=":
        return a == b
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    if op == ">=":
        return a >= b
    raise ValueError(op)


def _set_ok(comps, v):
    if not all(_test(op, b, v) for op, b in comps):
        return False
    if v[3]:
        return any(b is not None and b[3] and b[:3] == v[:3] for op, b in comps)
    return True


