import re

_IDENT = re.compile(r"[A-Za-z_][A-Za-z0-9_]*\Z")
_SEG = re.compile(r"(?:[A-Za-z_][A-Za-z0-9_]*|[0-9]+)\Z")
_UNDEF = object()
_FILTERS = {"upper": None, "lower": None, "length": None, "safe": None,
            "default": str, "join": str, "truncate": int}


def _tokenize(src):
    tokens = []
    pos = 0
    n = len(src)
    while pos < n:
        starts = [(src.find(o, pos), o) for o in ("{{", "{%", "{#")]
        starts = [(i, o) for i, o in starts if i != -1]
        if not starts:
            tokens.append(["text", src[pos:]])
            break
        i, opener = min(starts)
        if i > pos:
            tokens.append(["text", src[pos:i]])
        closer = {"{{": "}}", "{%": "%}", "{#": "#}"}[opener]
        j = src.find(closer, i + 2)
        if j == -1:
            raise ValueError("unclosed " + opener)
        body = src[i + 2:j]
        pos = j + 2
        if opener == "{#":
            tokens.append(["comment"])
            continue
        lstrip = body.startswith("-")
        if lstrip:
            body = body[1:]
        rstrip = body.endswith("-")
        if rstrip:
            body = body[:-1]
        tokens.append(["out" if opener == "{{" else "tag", body.strip(), lstrip, rstrip])
    for k, tok in enumerate(tokens):
        if tok[0] in ("out", "tag"):
            if tok[2] and k > 0 and tokens[k - 1][0] == "text":
                tokens[k - 1][1] = tokens[k - 1][1].rstrip(" \t\n\r")
            if tok[3] and k + 1 < len(tokens) and tokens[k + 1][0] == "text":
                tokens[k + 1][1] = tokens[k + 1][1].lstrip(" \t\n\r")
    return tokens


def _split_filters(text):
    parts, cur, inq = [], [], False
    for ch in text:
        if ch == '"':
            inq = not inq
        if ch == "|" and not inq:
            parts.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
    if inq:
        raise ValueError("unterminated string")
    parts.append("".join(cur))
    return parts


def _parse_expr(text):
    parts = _split_filters(text)
    path = parts[0].strip()
    segs = path.split(".")
    if not _IDENT.match(segs[0]) or not all(_SEG.match(s) for s in segs[1:]):
        raise ValueError("bad path %r" % path)
    filters = []
    for raw in parts[1:]:
        raw = raw.strip()
        name, sep, arg = raw.partition(":")
        name = name.strip()
        if name not in _FILTERS:
            raise ValueError("unknown filter %r" % name)
        kind = _FILTERS[name]
        if kind is None:
            if sep:
                raise ValueError("filter takes no argument")
            filters.append((name, None))
            continue
        if not sep:
            raise ValueError("filter needs an argument")
        arg = arg.strip()
        if kind is int:
            if not arg.isdigit():
                raise ValueError("integer argument expected")
            filters.append((name, int(arg)))
        else:
            if len(arg) < 2 or arg[0] != '"' or arg[-1] != '"' or '"' in arg[1:-1]:
                raise ValueError("string argument expected")
            filters.append((name, arg[1:-1]))
    for k, (name, _) in enumerate(filters):
        if name == "safe" and k != len(filters) - 1:
            raise ValueError("safe must be last")
    return (segs, filters)


def _parse(tokens):
    root = []
    stack = []  # (kind, node)
    current = root
    for tok in tokens:
        kind = tok[0]
        if kind == "text":
            current.append(("text", tok[1]))
        elif kind == "comment":
            continue
        elif kind == "out":
            if not tok[1]:
                raise ValueError("empty expression")
            current.append(("out", _parse_expr(tok[1])))
        else:
            words = tok[1].split()
            if not words:
                raise ValueError("empty tag")
            w = words[0]
            if w == "if":
                cond = _parse_cond(tok[1][2:])
                node = {"type": "if", "branches": [(cond, [])], "else": None}
                current.append(("if", node))
                stack.append(node)
                current = node["branches"][0][1]
            elif w == "elif":
                if not stack or stack[-1]["type"] != "if" or stack[-1]["else"] is not None:
                    raise ValueError("misplaced elif")
                cond = _parse_cond(tok[1][4:])
                stack[-1]["branches"].append((cond, []))
                current = stack[-1]["branches"][-1][1]
            elif w == "else":
                if len(words) != 1 or not stack or stack[-1]["else"] is not None:
                    raise ValueError("misplaced else")
                stack[-1]["else"] = []
                current = stack[-1]["else"]
            elif w == "for":
                if len(words) < 4 or words[2] != "in" or not _IDENT.match(words[1]) or words[1] == "loop":
                    raise ValueError("malformed for")
                expr_text = tok[1].split(None, 3)[3]
                node = {"type": "for", "var": words[1], "expr": _parse_expr(expr_text),
                        "body": [], "else": None}
                current.append(("for", node))
                stack.append(node)
                current = node["body"]
            elif w in ("endif", "endfor"):
                if len(words) != 1 or not stack or stack[-1]["type"] != w[3:]:
                    raise ValueError("unexpected " + w)
                stack.pop()
                current = _current_of(stack[-1]) if stack else root
            else:
                raise ValueError("unknown tag %r" % w)
    if stack:
        raise ValueError("unclosed block")
    return root


def _current_of(node):
    if node["type"] == "if":
        return node["else"] if node["else"] is not None else node["branches"][-1][1]
    return node["else"] if node["else"] is not None else node["body"]


def _parse_cond(text):
    text = text.strip()
    neg = False
    if text.startswith("not ") or text.startswith("not\t"):
        neg = True
        text = text[4:].strip()
    if not text:
        raise ValueError("empty condition")
    return (neg, _parse_expr(text))


def _lookup(segs, scopes, context):
    name = segs[0]
    value = _UNDEF
    for scope in reversed(scopes):
        if name in scope:
            value = scope[name]
            break
    else:
        value = context.get(name, _UNDEF)
    for seg in segs[1:]:
        if isinstance(value, dict):
            value = value.get(seg, _UNDEF)
        elif isinstance(value, (list, tuple)) and seg.isdigit() and int(seg) < len(value):
            value = value[int(seg)]
        else:
            return _UNDEF
        if value is _UNDEF:
            return _UNDEF
    return value


def _s(value):
    if value is _UNDEF or value is None:
        return ""
    if value is True:
        return "true"
    if value is False:
        return "false"
    return str(value)


def _eval(expr, scopes, context):
    segs, filters = expr
    value = _lookup(segs, scopes, context)
    safe = False
    for name, arg in filters:
        if name == "upper":
            value = _s(value).upper()
        elif name == "lower":
            value = _s(value).lower()
        elif name == "length":
            value = 0 if value is _UNDEF or value is None else len(value)
        elif name == "default":
            if value is _UNDEF or value is None or value == "":
                value = arg
        elif name == "join":
            value = "" if value is _UNDEF else arg.join(_s(v) for v in value)
        elif name == "truncate":
            text = _s(value)
            value = text[:arg] + "..." if len(text) > arg else text
        elif name == "safe":
            safe = True
    return value, safe


def _escape(text):
    return (text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            .replace('"', "&quot;").replace("'", "&#39;"))


def _render(nodes, scopes, context, out):
    for kind, node in nodes:
        if kind == "text":
            out.append(node)
        elif kind == "out":
            value, safe = _eval(node, scopes, context)
            text = _s(value)
            out.append(text if safe else _escape(text))
        elif kind == "if":
            for (neg, expr), body in node["branches"]:
                value, _ = _eval(expr, scopes, context)
                truth = value is not _UNDEF and bool(value)
                if truth != neg:
                    _render(body, scopes, context, out)
                    break
            else:
                if node["else"] is not None:
                    _render(node["else"], scopes, context, out)
        else:
            seq, _ = _eval(node["expr"], scopes, context)
            if seq is _UNDEF or seq is None:
                items = []
            elif isinstance(seq, dict):
                items = list(seq.keys())
            else:
                items = list(seq)
            if not items:
                if node["else"] is not None:
                    _render(node["else"], scopes, context, out)
                continue
            total = len(items)
            for i, item in enumerate(items):
                info = {"index": i + 1, "index0": i, "first": i == 0,
                        "last": i == total - 1, "length": total}
                scopes.append({node["var"]: item, "loop": info})
                _render(node["body"], scopes, context, out)
                scopes.pop()


def render(template, context):
    tree = _parse(_tokenize(template))
    out = []
    _render(tree, [], context, out)
    return "".join(out)

