_SEG = re.compile(r"(?:[A-Za-z_][A-Za-z0-9_]*|[0-9]+)\Z")
_UNDEF = object()
_FILTERS = {"upper": None, "lower": None, "length": None, "safe": None,
            "default": str, "join": str, "truncate": int}


def _tokenize(src):
    tokens = []
    pos = 0
    n = len(src)
    while pos < n:
        starts = [(src.find(o, pos), o) for o in ("{{", "{%", "{#")]
        starts = [(i, o) for i, o in starts if i != -1]
        if not starts:
            tokens.append(["text", src[pos:]])
            break
        i, opener = min(starts)
        if i > pos:
            tokens.append(["text", src[pos:i]])
        closer = {"{{": "}}", "{%": "%}", "{#": "#}"}[opener]
        j = src.find(closer, i + 2)
        if j == -1:
            raise ValueError("unclosed " + opener)
        body = src[i + 2:j]
        pos = j + 2
        if opener == "{#":
            tokens.append(["comment"])
            continue
        lstrip = body.startswith("-")
        if lstrip:
            body = body[1:]
        rstrip = body.endswith("-")
        if rstrip:
            body = body[:-1]
        tokens.append(["out" if opener == "{{" else "tag", body.strip(), lstrip, rstrip])
    for k, tok in enumerate(tokens):
        if tok[0] in ("out", "tag"):
            if tok[2] and k > 0 and tokens[k - 1][0] == "text":
                tokens[k - 1][1] = tokens[k - 1][1].rstrip(" \t\n\r")
            if tok[3] and k + 1 < len(tokens) and tokens[k + 1][0] == "text":
                tokens[k + 1][1] = tokens[k + 1][1].lstrip(" \t\n\r")
    return tokens


def _split_filters(text):
    parts, cur, inq = [], [], False
    for ch in text:
        if ch == '"':
            inq = not inq
        if ch == "|" and not inq:
            parts.append("".join(cur))
            cur = []
        else:
            cur.append(ch)
