import copy

_OPS = ("add", "remove", "replace", "move", "copy", "test")


def _tokens(pointer):
    if not isinstance(pointer, str):
        raise ValueError("pointer must be a string")
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError("pointer must start with /")
    out = []
    for raw in pointer[1:].split("/"):
        i = 0
        buf = []
        while i < len(raw):
            ch = raw[i]
            if ch == "~":
                if i + 1 < len(raw) and raw[i + 1] in "01":
                    buf.append("~" if raw[i + 1] == "0" else "/")
                    i += 2
                    continue
                raise ValueError("bad escape")
            buf.append(ch)
            i += 1
        out.append("".join(buf))
    return out


def _index(container, token, allow_end):
    if token == "-" and allow_end:
        return len(container)
    if not token.isdigit() or not token.isascii() or (len(token) > 1 and token[0] == "0"):
        raise ValueError("bad array index %r" % token)
    idx = int(token)
    limit = len(container) if allow_end else len(container) - 1
    if idx > limit:
        raise ValueError("index out of range")
    return idx


def _get(doc, tokens):
    cur = doc
    for tok in tokens:
        if isinstance(cur, dict):
            if tok not in cur:
                raise ValueError("missing key %r" % tok)
            cur = cur[tok]
        elif isinstance(cur, list):
            cur = cur[_index(cur, tok, False)]
        else:
            raise ValueError("cannot descend into scalar")
    return cur


def _add(doc, tokens, value):
    if not tokens:
        return value
    parent = _get(doc, tokens[:-1])
    last = tokens[-1]
    if isinstance(parent, dict):
        parent[last] = value
    elif isinstance(parent, list):
        parent.insert(_index(parent, last, True), value)
    else:
        raise ValueError("parent is not a container")
    return doc


def _remove(doc, tokens):
    if not tokens:
        raise ValueError("cannot remove the root")
    parent = _get(doc, tokens[:-1])
    last = tokens[-1]
    if isinstance(parent, dict):
        if last not in parent:
            raise ValueError("missing key")
        return parent.pop(last)
    if isinstance(parent, list):
        return parent.pop(_index(parent, last, False))
    raise ValueError("parent is not a container")


def _equal(a, b):
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if a is None or b is None:
        return a is None and b is None
    if isinstance(a, (int, float)) and isinstance(b, (int, float)):
        return a == b
    if isinstance(a, str) and isinstance(b, str):
        return a == b
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(_equal(x, y) for x, y in zip(a, b))
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(_equal(a[k], b[k]) for k in a)
    return False


