import datetime

D = datetime.datetime

def test_every_minute_is_strictly_after_and_drops_seconds():
    assert next_fire("* * * * *", D(2024, 3, 1, 10, 0, 30)) == D(2024, 3, 1, 10, 1)
    assert next_fire("* * * * *", D(2024, 3, 1, 10, 0)) == D(2024, 3, 1, 10, 1)
    assert next_fire("30 10 * * *", D(2024, 3, 1, 10, 30)) == D(2024, 3, 2, 10, 30)

def test_steps_ranges_and_lists():
    assert next_fire("*/15 * * * *", D(2024, 3, 1, 10, 7, 30)) == D(2024, 3, 1, 10, 15)
    assert next_fire("5-50/20 * * * *", D(2024, 3, 1, 10, 46)) == D(2024, 3, 1, 11, 5)
    assert next_fire("0 8,12-13 * * *", D(2024, 3, 1, 12, 0)) == D(2024, 3, 1, 13, 0)
    assert next_fire("10/20 * * * *", D(2024, 3, 1, 10, 36)) == D(2024, 3, 1, 10, 50)

def test_rollover_across_day_month_and_year():
    assert next_fire("0 0 * * *", D(2024, 12, 31, 23, 59, 59)) == D(2025, 1, 1, 0, 0)
    assert next_fire("15 3 1 * *", D(2024, 1, 31, 4, 0)) == D(2024, 2, 1, 3, 15)
    assert next_fire("0 12 * 6 *", D(2024, 7, 1)) == D(2025, 6, 1, 12, 0)

def test_leap_day_and_missing_days():
    assert next_fire("0 0 29 2 *", D(2024, 3, 1)) == D(2028, 2, 29, 0, 0)
    assert next_fire("0 0 29 2 *", D(2096, 3, 1)) == D(2104, 2, 29, 0, 0)
    assert next_fire("0 0 31 * *", D(2024, 4, 1)) == D(2024, 5, 31, 0, 0)

def test_both_day_fields_restricted_means_or():
    # 2024-09-13 is a Friday; the next 13th after that is 2024-10-13 (a Sunday)
    assert next_fire("0 0 13 * FRI", D(2024, 9, 13, 0, 0)) == D(2024, 9, 20, 0, 0)
    assert next_fire("0 0 13 * FRI", D(2024, 10, 11, 0, 0)) == D(2024, 10, 13, 0, 0)
    assert next_fire("0 0 1,15 * 3", D(2024, 3, 1, 0, 0)) == D(2024, 3, 6, 0, 0)

def test_star_prefixed_day_field_means_and():
    # */10 day-of-month = 1,11,21,31 ; Friday 2024-05-31 is the first match after March 1st
    assert next_fire("0 0 */10 * FRI", D(2024, 3, 1, 0, 0)) == D(2024, 5, 31, 0, 0)
    assert next_fire("0 0 1 * */7", D(2024, 3, 1, 0, 0)) == D(2024, 9, 1, 0, 0)
    assert next_fire("0 9 * * MON-FRI", D(2024, 3, 1, 9, 0)) == D(2024, 3, 4, 9, 0)

def test_sunday_as_seven_and_weekday_ranges_to_seven():
    assert next_fire("0 0 * * 7", D(2024, 3, 1)) == D(2024, 3, 3, 0, 0)
    assert next_fire("0 0 * * 5-7", D(2024, 3, 2, 1, 0)) == D(2024, 3, 3, 0, 0)
    assert next_fire("0 0 * * 6-7", D(2024, 3, 3, 1, 0)) == D(2024, 3, 9, 0, 0)

def test_names_are_case_insensitive():
    assert next_fire("0 0 1 jan-Mar *", D(2024, 3, 2)) == D(2025, 1, 1, 0, 0)
    assert next_fire("0 6 * * sat,SUN", D(2024, 3, 1)) == D(2024, 3, 2, 6, 0)
    assert next_fire("0 0 1 DEC *", D(2024, 3, 1)) == D(2024, 12, 1, 0, 0)

def test_macros():
    t = D(2024, 3, 1, 10, 30)
    assert next_fire("@hourly", t) == D(2024, 3, 1, 11, 0)
    assert next_fire("@daily", t) == D(2024, 3, 2, 0, 0)
    assert next_fire("@weekly", t) == D(2024, 3, 3, 0, 0)
    assert next_fire("@monthly", t) == D(2024, 4, 1, 0, 0)
    assert next_fire("@Annually", t) == D(2025, 1, 1, 0, 0)

def test_whitespace_between_fields():
    assert next_fire("  0\t12   * *  *  ", D(2024, 3, 1)) == D(2024, 3, 1, 12, 0)

def test_invalid_expressions_raise_value_error():
    bad = ["* * * *", "* * * * * *", "60 * * * *", "* 24 * * *", "* * 0 * *", "* * 32 * *", "* * * 13 *",
           "* * * * 8", "5-1 * * * *", "*/0 * * * *", "1,,2 * * * *", "* * * FOO *", "* * * * MONDAY",
           "@every", "a * * * *", "* * * JAN-FEB/x *", "-1 * * * *", "* * * * MON-"]
