        except ValueError:
            pass
        else:
            assert False, "expected ValueError for %r" % expr

def test_never_firing_expressions_raise_value_error():
    for expr in ["0 0 30 2 *", "0 0 31 4,6,9,11 *"]:
        try:
            next_fire(expr, D(2024, 1, 1))
        except ValueError:
            pass
        else:
            assert False, "expected ValueError for %r" % expr

def test_far_future_search_is_fast_and_correct():
    # day-of-month starts with '*' -> AND: Feb 1st or Feb 29th that is also a Monday
    assert next_fire("0 0 */28 2 MON", D(2021, 2, 2)) == D(2027, 2, 1, 0, 0)
    assert next_fire("59 23 31 12 *", D(2024, 1, 1)) == D(2024, 12, 31, 23, 59)

