import datetime as _dt

_MONTHS = {n: i + 1 for i, n in enumerate(
    ["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"])}
_DAYS = {n: i for i, n in enumerate(["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"])}
_MACROS = {"@yearly": "0 0 1 1 *", "@annually": "0 0 1 1 *", "@monthly": "0 0 1 * *",
           "@weekly": "0 0 * * 0", "@daily": "0 0 * * *", "@midnight": "0 0 * * *",
           "@hourly": "0 * * * *"}
_BOUNDS = [(0, 59, None), (0, 23, None), (1, 31, None), (1, 12, _MONTHS), (0, 7, _DAYS)]


def _value(text, lo, hi, names):
    if names is not None and text.upper() in names:
        v = names[text.upper()]
    elif text.isdigit() and text.isascii():
        v = int(text)
    else:
        raise ValueError("bad value %r" % text)
    if not lo <= v <= hi:
        raise ValueError("value out of range")
    return v


def _field(text, lo, hi, names):
    result = set()
    for item in text.split(","):
        if not item:
            raise ValueError("empty item")
        base, slash, step_text = item.partition("/")
        step = 1
        if slash:
            if not step_text.isdigit() or not step_text.isascii():
                raise ValueError("bad step")
            step = int(step_text)
            if step < 1:
                raise ValueError("bad step")
        if base == "*":
            a, b = lo, hi
        elif "-" in base:
            left, _, right = base.partition("-")
            a, b = _value(left, lo, hi, names), _value(right, lo, hi, names)
            if a > b:
                raise ValueError("reversed range")
        else:
            a = _value(base, lo, hi, names)
            b = hi if slash else a
        result.update(range(a, b + 1, step))
    return result


def _parse(expr):
    text = expr.strip()
    if text.startswith("@"):
        if text.lower() not in _MACROS:
            raise ValueError("unknown macro")
        text = _MACROS[text.lower()]
    fields = text.split()
    if len(fields) != 5:
        raise ValueError("need 5 fields")
    sets = [_field(f, lo, hi, names) for f, (lo, hi, names) in zip(fields, _BOUNDS)]
    dow = sets[4]
    if 7 in dow:
        dow.discard(7)
        dow.add(0)
    dom_star = fields[2].startswith("*")
    dow_star = fields[4].startswith("*")
    return sets, dom_star, dow_star


def next_fire(expr, after):
    (minutes, hours, doms, months, dows), dom_star, dow_star = _parse(expr)
    minutes = sorted(minutes)
    hours = sorted(hours)
    start = after.replace(second=0, microsecond=0) + _dt.timedelta(minutes=1)
    day = start.date()
    first = True
    for _ in range(366 * 13):
        if day.month in months:
            dom_ok = day.day in doms
            dow_ok = (day.isoweekday() % 7) in dows
            if (dom_ok or dow_ok) if not (dom_star or dow_star) else (dom_ok and dow_ok):
                for h in hours:
                    if first and h < start.hour:
                        continue
                    for m in minutes:
                        if first and h == start.hour and m < start.minute:
                            continue
                        return _dt.datetime(day.year, day.month, day.day, h, m)
        first = False
        day += _dt.timedelta(days=1)
    raise ValueError("expression never fires")

