import re

_BARE = re.compile(r"[A-Za-z0-9_-]+")
_DIG = r"[0-9][0-9_]*"
_DEC = r"[+-]?(?:0|[1-9](?:_?[0-9])*)"
_INT_RE = re.compile(r"(?:%s|0x[0-9A-Fa-f](?:_?[0-9A-Fa-f])*|0o[0-7](?:_?[0-7])*|0b[01](?:_?[01])*)\Z" % _DEC)
_FLOAT_RE = re.compile(r"%s(?:\.%s)?(?:[eE][+-]?%s)?\Z" % (_DEC, _DIG, _DIG))
_SPECIAL = {"inf": float("inf"), "+inf": float("inf"), "-inf": float("-inf"),
            "nan": float("nan"), "+nan": float("nan"), "-nan": float("nan")}
_ESC = {"b": "\b", "t": "\t", "n": "\n", "f": "\f", "r": "\r", '"': '"', "\\": "\\"}
_STOP = " \t\n,]}#"


class _Err(Exception):
    pass


class _Parser:
    def __init__(self, text):
        self.s = text.replace("\r\n", "\n")
        self.i = 0
        self.line = 1
        self.root = {}
        self.meta = {id(self.root): "header"}
        self.aot = set()
        self.keep = []

    # -- low level -------------------------------------------------
    def peek(self):
        return self.s[self.i] if self.i < len(self.s) else ""

    def ws(self):
        while self.peek() in (" ", "\t") and self.peek():
            self.i += 1

    def ws_nl(self):
        while True:
            c = self.peek()
            if c in (" ", "\t") and c:
                self.i += 1
            elif c == "\n":
                self.i += 1
                self.line += 1
            elif c == "#":
                while self.peek() not in ("\n", ""):
                    self.i += 1
            else:
                return

    def new_table(self, kind):
        t = {}
        self.meta[id(t)] = kind
        self.keep.append(t)
        return t

    # -- strings / keys ----------------------------------------------
    def basic_string(self):
        self.i += 1
        out = []
        while True:
            c = self.peek()
            if c in ("", "\n"):
                raise _Err("unterminated string")
            self.i += 1
            if c == '"':
                return "".join(out)
            if c == "\\":
                e = self.peek()
                self.i += 1
                if e in _ESC:
                    out.append(_ESC[e])
                elif e in ("u", "U"):
                    n = 4 if e == "u" else 8
                    h = self.s[self.i:self.i + n]
                    if len(h) != n or not all(ch in "0123456789abcdefABCDEF" for ch in h):
                        raise _Err("bad unicode escape")
                    cp = int(h, 16)
                    if cp > 0x10FFFF:
                        raise _Err("bad code point")
                    out.append(chr(cp))
                    self.i += n
                else:
                    raise _Err("bad escape")
            else:
                out.append(c)

    def literal_string(self):
        self.i += 1
        j = self.i
        while self.peek() not in ("'", "\n", ""):
            self.i += 1
        if self.peek() != "'":
            raise _Err("unterminated string")
        text = self.s[j:self.i]
        self.i += 1
        return text

    def key(self):
        parts = []
        while True:
            self.ws()
            c = self.peek()
            if c == '"':
                parts.append(self.basic_string())
            elif c == "'":
                parts.append(self.literal_string())
            else:
                m = _BARE.match(self.s, self.i)
                if not m:
                    raise _Err("bad key")
                parts.append(m.group())
                self.i = m.end()
            self.ws()
            if self.peek() == ".":
                self.i += 1
                continue
            return parts

    # -- values ------------------------------------------------------
    def value(self):
        c = self.peek()
        if c == '"':
            return self.basic_string()
        if c == "'":
            return self.literal_string()
        if c == "[":
            return self.array()
        if c == "{":
            return self.inline_table()
        j = self.i
        while self.peek() and self.peek() not in _STOP:
            self.i += 1
        tok = self.s[j:self.i]
        if tok == "true":
            return True
        if tok == "false":
            return False
        if tok in _SPECIAL:
            return _SPECIAL[tok]
        if _INT_RE.match(tok):
            t = tok.replace("_", "")
            if t[:2] in ("0x", "0o", "0b"):
                return int(t[2:], {"0x": 16, "0o": 8, "0b": 2}[t[:2]])
            return int(t)
        if _FLOAT_RE.match(tok):
            return float(tok.replace("_", ""))
        raise _Err("bad value %r" % tok)

    def array(self):
        self.i += 1
        out = []
        while True:
            self.ws_nl()
            if self.peek() == "]":
                self.i += 1
                return out
            if self.peek() == "":
                raise _Err("unterminated array")
            out.append(self.value())
            self.ws_nl()
            c = self.peek()
            if c == ",":
                self.i += 1
            elif c == "]":
                self.i += 1
                return out
            else:
                raise _Err("expected , or ]")

    def inline_table(self):
        self.i += 1
        table = self.new_table("building")
        self.ws()
        if self.peek() == "}":
            self.i += 1
        else:
            while True:
                self.keyval(table, inline=True)
                self.ws()
                c = self.peek()
                if c == ",":
                    self.i += 1
                    self.ws()
                    if self.peek() == "}":
                        raise _Err("trailing comma in inline table")
                elif c == "}":
                    self.i += 1
                    break
                else:
                    raise _Err("expected , or }")
        self.freeze(table)
        return table

    def freeze(self, value):
        if isinstance(value, dict):
            self.meta[id(value)] = "inline"
            for v in value.values():
                self.freeze(v)
        elif isinstance(value, list):
            for v in value:
                self.freeze(v)

    # -- statements --------------------------------------------------
    def keyval(self, table, inline=False):
        keys = self.key()
        if self.peek() != "=":
            raise _Err("expected =")
        self.i += 1
        self.ws()
        if self.peek() in ("", "\n", "#"):
            raise _Err("missing value")
        value = self.value()
        ok_kind = "building" if inline else "dotted"
        t = table
        for k in keys[:-1]:
            if k not in t:
                t[k] = self.new_table(ok_kind)
            v = t[k]
            if not isinstance(v, dict) or self.meta.get(id(v)) != ok_kind:
                raise _Err("cannot extend %r with dotted keys" % k)
            t = v
        if keys[-1] in t:
            raise _Err("duplicate key %r" % keys[-1])
        t[keys[-1]] = value

    def header(self):
        self.i += 1
        is_aot = self.peek() == "["
        if is_aot:
            self.i += 1
        keys = self.key()
        if self.peek() != "]":
            raise _Err("expected ]")
        self.i += 1
        if is_aot:
            if self.peek() != "]":
                raise _Err("expected ]]")
            self.i += 1
        t = self.root
        for k in keys[:-1]:
            if k not in t:
                t[k] = self.new_table("implicit")
            v = t[k]
            if isinstance(v, list) and id(v) in self.aot:
                v = v[-1]
            elif not isinstance(v, dict) or self.meta.get(id(v)) == "inline":
                raise _Err("cannot define table under %r" % k)
            t = v
        last = keys[-1]
        if is_aot:
            if last not in t:
                arr = []
                self.aot.add(id(arr))
                self.keep.append(arr)
                t[last] = arr
            arr = t[last]
            if not (isinstance(arr, list) and id(arr) in self.aot):
                raise _Err("%r is not an array of tables" % last)
            new = self.new_table("header")
            arr.append(new)
            return new
        if last in t:
            v = t[last]
            if isinstance(v, dict) and self.meta.get(id(v)) == "implicit":
                self.meta[id(v)] = "header"
                return v
            raise _Err("table %r already defined" % last)
        new = self.new_table("header")
        t[last] = new
        return new

    def parse(self):
        current = self.root
        while True:
            self.ws()
            c = self.peek()
            if c == "":
                return self.root
            if c == "\n":
                self.i += 1
                self.line += 1
                continue
            if c == "#":
                while self.peek() not in ("\n", ""):
                    self.i += 1
                continue
            start = self.line
            try:
                if c == "[":
                    current = self.header()
                else:
                    self.keyval(current)
                self.ws()
                if self.peek() == "#":
                    while self.peek() not in ("\n", ""):
                        self.i += 1
                if self.peek() not in ("\n", ""):
                    raise _Err("unexpected text after statement")
            except _Err as exc:
                raise ValueError("line %d: %s" % (start, exc)) from None


def parse_config(text):
    return _Parser(text).parse()

