def earliest_connection(n, edges, queries):
    # union by size WITHOUT path compression; each link remembers its time.
    # The answer for (a, b) is the largest link time on the tree path a..b.
    parent = list(range(n))
    size = [1] * n
    when = [0] * n
    for t, (u, v) in enumerate(edges, 1):
        while parent[u] != u:
            u = parent[u]
        while parent[v] != v:
            v = parent[v]
        if u == v:
            continue
        if size[u] < size[v]:
            u, v = v, u
        parent[v] = u
        size[u] += size[v]
        when[v] = t
    out = []
    for a, b in queries:
        if a == b:
            out.append(0)
            continue
        # climb from the endpoint whose next link is older; the path is
        # monotone in time, so the two climbs meet at the LCA.
        best = 0
        while a != b:
            if parent[a] == a and parent[b] == b:
                best = -1
                break
            if parent[a] == a or (parent[b] != b and when[b] < when[a]):
                a, b = b, a
            # now climb a (its link time is the smaller one available)
            if when[a] > best:
                best = when[a]
            a = parent[a]
        out.append(best)
    return out

