    # number of pairs i < j (a sorted) with a[j] - a[i] <= d
    count = 0
    i = 0
    for j, x in enumerate(a):
        limit = x - d
        while a[i] < limit:
            i += 1
        count += j - i
    return count


def kth_pair_distance(nums, k):
    n = len(nums)
    if k < 1 or k > n * (n - 1) // 2:
        raise ValueError("k out of range")
    a = sorted(nums)
    lo, hi = 0, a[-1] - a[0]
    while lo < hi:
        mid = (lo + hi) // 2
        if _count_at_most(a, mid) >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

