import random

def _reference(nums, queries):
    return [sum(1 for v in nums[l:r + 1] if v <= x) for l, r, x in queries]

def _big(n, q, vspan, seed, short=None):
    rng = random.Random(seed)
    r = rng.randrange
    nums = [r(-vspan, vspan + 1) for _ in range(n)]
    queries = []
    for _ in range(q):
        a = r(n)
        b = min(n - 1, a + r(short)) if short else r(n)
        if a > b:
            a, b = b, a
        queries.append((a, b, r(-vspan - 2, vspan + 3)))
    return nums, queries

def _digest(res):
    return (sum(res), sum((i % 1009 + 1) * v for i, v in enumerate(res)) % 1_000_000_007)

def test_example():
    assert count_at_most([5, 1, 4, 1, 3], [(0, 4, 3), (1, 3, 1), (2, 2, 3), (0, 0, 5)]) == [3, 2, 0, 1]

def test_threshold_equal_to_values_is_counted():
    assert count_at_most([2, 2, 2], [(0, 2, 2), (0, 2, 1), (1, 1, 2)]) == [3, 0, 1]

def test_thresholds_outside_value_range():
    nums = [-5, 0, 7]
    assert count_at_most(nums, [(0, 2, -10**9), (0, 2, 10**9), (1, 2, -1)]) == [0, 3, 0]

def test_answers_keep_query_order():
    nums = [3, 1, 2]
    assert count_at_most(nums, [(0, 2, 3), (0, 2, 1), (0, 2, 2), (0, 0, 2)]) == [3, 1, 2, 0]

def test_range_boundaries_are_inclusive():
    nums = [1, 1, 1, 1, 1]
    assert count_at_most(nums, [(0, 0, 1), (4, 4, 1), (1, 3, 1), (0, 4, 1)]) == [1, 1, 3, 5]

def test_single_element():
    assert count_at_most([4], [(0, 0, 3), (0, 0, 4)]) == [0, 1]

def test_random_small_cases_match_reference():
    rng = random.Random(17)
    for _ in range(300):
        n = rng.randrange(1, 12)
        nums = [rng.randrange(-3, 4) for _ in range(n)]
        qs = []
        for _ in range(8):
            a, b = sorted((rng.randrange(n), rng.randrange(n)))
            qs.append((a, b, rng.randrange(-4, 5)))
        assert count_at_most(nums, qs) == _reference(nums, qs)

def test_large_wide_values_long_ranges():
    nums, queries = _big(40_000, 40_000, 10**9, 51)
    assert _digest(count_at_most(nums, queries)) == (264771300, 695893109)

def test_large_few_distinct_values():
    nums, queries = _big(40_000, 40_000, 3, 52)
    assert _digest(count_at_most(nums, queries)) == (289497397, 56858352)

def test_large_mixed_short_ranges():
    nums, queries = _big(40_000, 40_000, 1000, 53, short=25_000)
    assert _digest(count_at_most(nums, queries)) == (196520567, 420809895)
